PRICE_CENTS = 75
STOCK = 2
def quote(quantity):
    if type(quantity) is not int or quantity < 0:
        raise ValueError('quantity must be a nonnegative integer')
    return {'quote': {'amount_minor': PRICE_CENTS * quantity, 'currency': 'USD'},
            'status': 'available' if quantity <= STOCK else 'unavailable'}

